function localizeReport(html) {
  if (typeof LANG === "undefined" || LANG !== "fr") return html;
  const sorted = REPORT_FR.slice().sort((a, b) => b[0].length - a[0].length);
  let out = html;
  for (const [en, fr] of sorted) {
    const pattern = en.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/ /g, "\\s+");
    out = out.replace(new RegExp(pattern, "g"), fr);
  }
  return out;
}
